    "en": "…when they look at the article about you…",
    "note": "In casual speech, 目え can represent a drawn-out pronunciation of 目 with the object particle を omitted. This is conversational usage, not necessarily a grammatical mistake. Yoshiko also gives 歯あ抜いた (歯を抜いた: had a tooth pulled out) and 手え貸して (手を貸して: give me a hand) as examples.",
